INSERT INTO imdb.movie VALUES ('3492042', 'The Thousand Miles', NULL, NULL, NULL, 'In 1950s Italy, two middle-aged brothers go on a magical odyssey through their past as they take part in the world''s most beautiful car race: the Mille Miglia.');
INSERT INTO imdb.movie VALUES ('1442054', 'Two Telegrams', NULL, NULL, NULL, NULL);
