INSERT INTO imdb.person VALUES ('2148911', 'Wunmi Mosaku was born on July 31, 1986 in Zaria, Nigeria as Oluwunmi Olapeju Mosaku. She is an actress, known for Batman v Superman: Dawn of Justice (2016), Philomena (2013) and Fantastic Beasts and Where to Find Them (2016).::Anonymous', 'Oluwunmi Olapeju', 'Mosaku', '1986-07-31', NULL, 'Wunmi Mosaku');
