INSERT INTO imdb.person VALUES ('7599338', 'Evan was born in Joliet IL. He has 4 siblings 1 brother and 3 sisters. His older siblings have been acting for almost a decade. He booked his very 1st audition. He loves video games and playing outside. He wants to be a police officer when he get older. Evan is the third of five kids.::Joyce E Thurston', NULL, NULL, NULL, NULL, 'Evan Gilliam');
INSERT INTO imdb.person VALUES ('7599339', 'Leah was born in Joliet IL. She has 4 siblings 2 brothers and 2 sisters. Her older siblings have been acting for almost a decade. She booked her very 1st audition. She loves video games and playing outside. Leah is the forth of five kids. She loves to talk! Very sweet child.::Joyce E Thurston', NULL, NULL, NULL, NULL, 'Leah Gilliam');
