INSERT INTO imdb.person VALUES ('2868742', 'Dayl Johns was born on March 19, 1980 in Detroit, Michigan, USA. She is an actress, known for Batman v Superman: Dawn of Justice (2016), Transformers: Age of Extinction (2014) and My Ranch Memories (2017).::Anonymous', NULL, NULL, '1980-03-19', NULL, 'Dayl Johns');
INSERT INTO imdb.person VALUES ('7463407', 'Brian Jones is known for his work on Batman v Superman: Dawn of Justice (2016), White Boy Rick (2018) and Chicago P.D. (2014).::Anonymous', NULL, NULL, NULL, NULL, 'Brian Jones');
