INSERT INTO imdb.person VALUES ('0378363', 'Jeff Hephner was born on June 22, 1975 in Sand Creek, Michigan, USA as Jeffrey Lane Hephner. He is an actor, known for Agent X (2015), Interstellar (2014) and Boss (2011). He has been married to Heather Sylvia Adams since 2002. They have three children.::Anonymous', 'Jeffrey Lane', 'Hephner', '1975-06-22', NULL, 'Jeff Hephner');
INSERT INTO imdb.person VALUES ('1285387', 'Lena Georgas was born on July 5, 1979 in New York City, New York, USA as Marie-Elena Georgas. She is an actress and producer, known for Westworld (2016), Interstellar (2014) and Ray Donovan (2013).::Anonymous', 'Marie-Elena', 'Georgas', '1979-07-05', NULL, 'Lena Georgas');
