INSERT INTO imdb.person VALUES ('0660013', 'Carl Paoli has been a professional stuntman and safely performed big stunts in major feature films and television shows for over 20 years. He is a well rounded stuntman with skills in motorcycles, bicycles and cars. He is also passionate about and has advanced ratings in aerial work such as paragliding USHPA, building climbing and mountain climbing. He is certified in SCUBA and trained at The Rick Seaman Stunt Driving School.::Carl Paoli', NULL, NULL, NULL, NULL, 'Carl Paoli');
INSERT INTO imdb.person VALUES ('5236137', 'Paul Pikus is an actor and producer, known for The Atticus Institute (2015), Man of Steel (2013) and Pro Reo (2012).::Anonymous', NULL, NULL, NULL, NULL, 'Paul Pikus');
