INSERT INTO imdb.person VALUES ('0722013', 'Rondel Reynoldson was born in small town Saskatchewan and grew up in small town British Columbia, Canada. Rondel brings a genuine love and curiosity for the craft of acting to her work. She has performed on stage in Vancouver, Toronto and Montreal and has acted in film and television projects ranging from local independent films to Hollywood blockbusters for more than 20 years.::Rondel Reynoldson', NULL, NULL, NULL, NULL, 'Rondel Reynoldson');
