INSERT INTO imdb.person VALUES ('4946906', 'Rayman Jilani is an actor, known for The Dark Knight Rises (2012), Rise of the Zombies (2012) and Lifeline (2014).::Anonymous', NULL, NULL, NULL, NULL, 'Rayman Jilani');
INSERT INTO imdb.person VALUES ('2576747', 'Silvia Lombardo was born in Rome, Italy. At the age of 17 she moved from Rome to England. After a Degree from the University of Exeter where she mastered her knowledge of languages, she pursued a career in acting and dancing studying at the London Studio Centre (United Kingdom) and the Accademia Nazionale di Danza (Rome, Italy). She has appeared in numerous stage productions, commercials and films. Silvia speaks fluent English, Italian, French and Spanish and has aristocratic roots.::-', NULL, NULL, NULL, NULL, 'Silvia Lombardo');
INSERT INTO imdb.person VALUES ('4467795', 'Colin Snyder is an actor, known for The Dark Knight Rises (2012), L.A. Noire (2011) and Bloody Solstice (2013).::Anonymous', NULL, NULL, NULL, NULL, 'Colin Snyder');
