INSERT INTO imdb.person VALUES ('0970985', 'LeJon is an actor and producer, known for Pirates of the Caribbean: Dead Man''s Chest (2006), Community (2009) and Cardboard Boxer (2016).::Anonymous', NULL, NULL, NULL, NULL, 'LeJon');
