INSERT INTO imdb.person VALUES ('4178216', 'David Michael Plowman was born on March 17, 1979 in Ann Arbor, Michigan, USA. He is known for his work on The Dark Knight Rises (2012), Legend (2013) and Fall Away (2011). He has been married to Elizabeth Mcdaniel since October 10, 2010. He was previously married to Heather E Hall.::Anonymous', NULL, NULL, '1979-03-17', NULL, 'David Michael Plowman');
