INSERT INTO imdb.person VALUES ('4005186', 'Nial is a graduate of Henry Sibley High School in Mendota Heights, MN in 2008. He graduate from Minneapolis Community & Technical College. He studied Editing & Post Production and Directing & Producing concentrations in Cinema Division at MCTC. He was a film Major at Augsburg College in Minneapolis. He is employed by Cub Foods West St. Paul from fall 2006 until fall 2012.::Anonymous Rex', NULL, NULL, NULL, NULL, 'Nial Nelson-Hopkins');
