INSERT INTO imdb.person VALUES ('5755497', 'Adam Night is an actor, known for The Dark Knight Rises (2012), Avengers Grimm (2015) and Unrequited Love (2013).::Anonymous', NULL, NULL, NULL, NULL, 'Adam Night');
INSERT INTO imdb.person VALUES ('2290509', 'Troy Polamalu was born on April 19, 1981 in Garden Grove, California, USA as Troy Aumua Polamalu. He is an actor, known for Super Bowl XLIII (2009), Super Bowl XLV (2011) and Super Bowl XL (2006). He has been married to Theodora Holmes since January 27, 2005. They have two children.::Anonymous', 'Troy Aumua', 'Polamalu', '1981-04-19', NULL, 'Troy Polamalu');
INSERT INTO imdb.person VALUES ('4118324', 'Maurkice Pouncey was born on July 24, 1989 in Ardmore, Oklahoma, USA. He is an actor, known for Super Bowl XLV (2011), The Dark Knight Rises (2012) and NBC Sunday Night Football (2006).::Anonymous', NULL, NULL, '1989-07-24', NULL, 'Maurkice Pouncey');
