INSERT INTO imdb.person VALUES ('1792648', 'Joseph O''Brien is an actor and producer, known for Child''s Play (2012), Jean Claude: The Gumming Zombie (2009) and The Dark Knight Rises (2012).::Anonymous', NULL, NULL, NULL, NULL, 'Joseph O''Brien');
INSERT INTO imdb.person VALUES ('2335340', 'Shaun O''Donnell was born in Johnstown, Pennsylvania. He grew up with a creative drive which was reflected in his love for the individual sports of Skateboarding and Snowboarding. Always looking for a new adventure; his travels took him to Wilmington, North Carolina. It was on the back lot of Screen Gems Studios where he found his calling. Shaun was an extra in a large commercial production, and fell in love with Acting and Filmmaking. Since then, he has worked on many productions as an Actor, Writer, Producer, and Director.::Anonymous', 'Shaun Michael', 'O''Donnell', '1973-08-07', NULL, 'Shaun O''Donnell');
INSERT INTO imdb.person VALUES ('4630298', 'Matt O''Gorman is an actor, known for The Dark Knight Rises (2012), Die Another Deity (2011) and Marital Problems (2017).::Anonymous', NULL, NULL, NULL, NULL, 'Matt O''Gorman');
