INSERT INTO imdb.person VALUES ('0656275', 'Matt Page holds a Bachelor''s Degree in Moving Image Arts from the College of Santa Fe. In 2006, Page co-founded Riffraff New Media, a New Mexico-based production company through which he has written and directed multiple award-winning short films that have screened all over the world. Page has appeared regularly on the WGN show "Manhattan" and has been seen in several feature films. He is also the creator and star of "Enter The Dojo", a comedic web series that has achieved over 11 million views on YouTube.::Matt Page', NULL, NULL, NULL, NULL, 'Matthew Page');
INSERT INTO imdb.person VALUES ('1254942', 'Lora Martinez-Cunningham was born in Albuquerque, New Mexico, USA. She is an actress, known for The Book of Eli (2010), Sicario (2015) and Maze Runner: The Scorch Trials (2015).::Anonymous', NULL, NULL, NULL, NULL, 'Lora Martinez-Cunningham');
