INSERT INTO imdb.person VALUES ('8968940', 'Raised in Urbana, Ohio, Ashley D. Evans received her Associates Degree in Radio & Television from the International College of Broadcasting in Dayton, Ohio and received a Master''s Degree in Criminal Justice Administration from Urbana University in Urbana, Ohio. Her love for film, television, and print media has ignited the passion again to pursue her modeling and acting career.::Ashley D. Karns Evans', 'Ashley D.', 'Karns', '1983-08-17', NULL, 'Ashley D. Evans');
