INSERT INTO imdb.person VALUES ('8779982', 'Daniel Lamont was born in Cleveland, Ohio. Daniel was a chef for over 20 years for a local Italian restaurant in Middleburg heights. Currently, Daniel is an entrepreneur and runs his own cleaning company. He also works as a machine operator by day for an electrical insulation company in his hometown. In 2016 Daniel got his first acting roles for the movie My Friend Dahmer, and the hit television series The Outsiders.::Daniel Lamont', NULL, NULL, NULL, NULL, 'Daniel Lamont');
INSERT INTO imdb.person VALUES ('2807747', 'Joseph Marco is an actor, known for Sabel (2010), On the Job (2013) and Talk Back and You''re Dead (2014).::Anonymous', NULL, NULL, NULL, NULL, 'Joseph Marco');
