INSERT INTO imdb.person VALUES ('8306654', 'Robbie McLean was born in Johannesburg, South Africa. He is known for his role as Ben MacDonald in The Baobab Boys (2016) as well as Toby in Stephen Kings'' The Dark Tower (2017). Robbie is a character actor and is represented by Moonyeen Lee and Associates (MLASA) in Johannesburg, South Africa. Robbie now resides in Los Angeles California.::Robbie McLean', NULL, NULL, NULL, NULL, 'Robbie McLean');
INSERT INTO imdb.person VALUES ('3003116', 'Mark Elderkin was born on June 21, 1981 in Mbabane, Swaziland. He is known for his work on Black Sails (2014), Dark Tide (2012) and Death Race: Inferno (2013).::Anonymous', NULL, NULL, '1981-06-21', NULL, 'Mark Elderkin');
