INSERT INTO imdb.person VALUES ('3462243', 'Richard Lothian is an actor already making waves in both the international and South African film community with such movies as Northmen, Gettysburg and Momentum. Based in South Africa he takes full advantage of the natural playground of the stunning Cape Town landscape and can often be found surfing or honing himself with physical challenges of all kinds.::Susan Rabe - Agent', NULL, NULL, NULL, NULL, 'Richard Lothian');
INSERT INTO imdb.person VALUES ('1923179', 'Larry Nuñez was born as Lawrence Rene Nuñez. He is known for his work on Sicario (2015), Law & Order: Special Victims Unit (1999) and Boardwalk Empire (2010).::Anonymous', 'Lawrence Rene', 'Nuñez', NULL, NULL, 'Larry Nuñez');
