INSERT INTO imdb.person VALUES ('0561728', 'Jeremy Maxwell was born on April 30, 1975 in Grants Pass, Oregon, USA. He is known for his work on Captain America: The Winter Soldier (2014), Finding Dory (2016) and Il grande Gatsby (2013). He has been married to Megahn Perry since 2010. They have one child.::Anonymous', NULL, NULL, '1975-04-30', NULL, 'Jeremy Maxwell');
