INSERT INTO imdb.person VALUES ('2297424', 'Daniel Mora is known for his work on Now You See Me (2013), The Lego Movie (2014) and Man on Fire (2004).::Anonymous', NULL, NULL, NULL, NULL, 'Daniel Mora');
