INSERT INTO imdb.person VALUES ('7158359', 'Nolan was born August 16th 1986 in Palm Springs, California, and was raised in Twentynine Palms, California. Nolan has been a resident of San Diego CA, Long Beach, CA, Los Angeles CA, and New Orleans, Louisiana A Great White Shark damaged Nolan''s left hand and arm during a surfing trip off the coast of San Diego.::Nolan Cummings', NULL, NULL, NULL, NULL, 'Nolan Cummings');
