INSERT INTO imdb.person VALUES ('6093204', 'Bekah Mulberg was born on February 20, 1994 in Cherry Hill, New Jersey, USA as Rebecca Rose. She is known for her work on Orange Is the New Black (2013), Dying to Run (2018) and Acts and Intermissions (2017).::Anonymous', 'Rebecca', 'Rose', '1994-02-20', NULL, 'Bekah Mulberg');
INSERT INTO imdb.person VALUES ('7516086', 'Ryan Canney was born on June 19, 1991 in Athens, Georgia, USA. He is a director and actor, known for City of Ticks (2017), Cirino (2013) and Dead End (2011).::Anonymous', NULL, NULL, '1991-06-19', NULL, 'Ryan Canney');
INSERT INTO imdb.person VALUES ('8348015', 'Justine Denea Cassady is an actress, known for The Wolf of Wall Street (2013) and Wetlands (2017).::Anonymous', NULL, NULL, NULL, NULL, 'Justine Denea Cassady');
