INSERT INTO imdb.person VALUES ('6346551', 'Nicholas Ferrara is an actor, known for The Wolf of Wall Street (2013), Exogenesis (2014) and Sound/Vision.::Anonymous', NULL, NULL, NULL, NULL, 'Nicholas Ferrara');
INSERT INTO imdb.person VALUES ('2935442', 'Originally from Germany, Fleck left Fashion to pursue acting and directing in NYC. Her love for theater, led her to direct her first play "Gentrified Minds" which premiered at the Downtown Urban Theater Festival in 2011. In 2015 she directed two avant-garde short films. "The P/Flight of the New York Artist" and "Spindled Tears".::B Hardwicke', 'Corinna Jeanine', 'Fleck', '1976-04-14', NULL, 'Corinna Jeanine Fleck');
INSERT INTO imdb.person VALUES ('5075677', 'Brian Colin Foley is an actor, known for Orange Is the New Black (2013), Snowpiercer (2013) and The Mysteries of Laura (2014).::Anonymous', NULL, NULL, NULL, NULL, 'Brian Colin Foley');
