INSERT INTO imdb.person VALUES ('4650037', 'Wanda Leigh is an actress, known for Wicked Blood (2014), Dallas Buyers Club (2013) and Could This Be Love (2014).::Anonymous', NULL, NULL, NULL, NULL, 'Wanda Leigh');
