INSERT INTO imdb.person VALUES ('4305826', 'David was born in Tulsa, Oklahoma to a nurse and a Navy man. He was adopted by his aunt when he was nine years old. New Orleans has been his home for the past twenty years. Before that, David lived in Colorado, California, Oklahoma, Tennessee and Alabama. Along the way, he learned medicine, piloting a plane, Information Technology, baseball and surfing.::DC', NULL, NULL, NULL, NULL, 'David A Cole');
