INSERT INTO imdb.person VALUES ('4237609', 'Monica R. Harris is a SAG-E actor, model, singer, and theatre arts professional based in New Orleans, LA with a B.A. in Theatre Arts from The College of Music & Fine Arts at Loyola University New Orleans. Monica will AD the Regional Premiere of Tony-Nominated play "Airline Highway" by Lisa d''Amour this fall with Souhern Rep. She is the eldest daughter of Albert Lavon Harris and Marilou Cayetano Harris.::mrh', 'Monica Renée', 'Harris', '1985-06-19', NULL, 'Monica R. Harris');
