INSERT INTO imdb.person VALUES ('0447729', 'Tommy G. Kendrick is a native Texan who started his professional acting career at the Dallas Theater Center. There he worked with director Paul Baker and the late Preston Jones on the original productions of Jones'' ''The Oldest Living Graduate'', ''LuAnn Hampton Laverty Oberlander'' and ''The Last Meeting of the Knights of the White Magnolia''. Kendrick spent a number of years in Los Angeles before returning to live and work in his native Texas where he happily resides with his wife and son.::Anonymous', NULL, NULL, NULL, NULL, 'Tommy G. Kendrick');
