INSERT INTO imdb.person VALUES ('2016723', 'Eve Hewson was born on July 7, 1991 in Ireland as Memphis Eve Hewson. She is an actress, known for Bridge of Spies (2015), This Must Be the Place (2011) and Enough Said (2013).::Anonymous', 'Memphis Eve', 'Hewson', '1991-07-07', NULL, 'Eve Hewson');
INSERT INTO imdb.person VALUES ('2423358', 'Tim Minchin was born on October, 1975, as Timothy David Minchin, and was brought up in Perth, Western Australia. He is an actor, comedian, musician, writer, and director known for Californication (2007), Larrikins (2018), and Tim Minchin and the Heritage Orchestra (2011). He is the composer lyricist of the Broadway musicals, Matilda and Groundhog Day. He has been married to Sarah since 2001. They have two children.::Tim Minchin', 'Timothy David', 'Minchin', '1975-10-07', NULL, 'Tim Minchin');
INSERT INTO imdb.person VALUES ('3300102', 'Lucy Angelo was born in Laguna Beach, California, USA. She is an actress, known for Something New (2015), Chris''s Briss (2013) and Some Guy Who Kills People (2011).::Anonymous', NULL, NULL, NULL, NULL, 'Lucy Angelo');
