INSERT INTO imdb.person VALUES ('2663090', 'Kembe Sorel was born in 1975 in Hungary. He is an actor, known for 100 Feet (2008), Cop Mortem (2016) and Robin Hood (2018).::Anonymous', NULL, NULL, NULL, NULL, 'Kembe Sorel');
