INSERT INTO imdb.person VALUES ('5986857', 'Keegan Kuhn is an award-winning documentary filmmaker, director, producer and professional musician. He is the operator of First Spark Media, a film and video production company tailored to creating stunning visual media for non-profit organizations and conscientious businesses. His films focus on social justice topics of environmental, animal and human rights issues.::first spark', NULL, NULL, NULL, NULL, 'Keegan Kuhn');
