INSERT INTO imdb.person VALUES ('0169256', 'Bobby Cohen is a producer, known for Now You See Me (2013), Revolutionary Road (2008) and Memoirs of a Geisha (2005).::Anonymous', NULL, NULL, NULL, NULL, 'Bobby Cohen');
