INSERT INTO imdb.person VALUES ('5132341', 'Marisela Zumbado is an actress, known for Jack Reacher: Punto di non ritorno (2016), The DUFF (2015) and Pitch Perfect 2 (2015).::Anonymous', NULL, NULL, NULL, NULL, 'Marisela Zumbado');
INSERT INTO imdb.person VALUES ('5849654', 'Alexandra Lucchesi is an actress, known for Jack Reacher: Punto di non ritorno (2016), The Dunning Man (2017) and The Demented (2013).::Anonymous', NULL, NULL, NULL, NULL, 'Alexandra Lucchesi');
