INSERT INTO imdb.person VALUES ('9012788', 'Gary Clarke is an actor, known for La mummia (2017).::Anonymous', NULL, NULL, NULL, NULL, 'Gary Clarke');
INSERT INTO imdb.person VALUES ('0477465', 'Theo Kypri was born in London, England. He attended Highbury Grove Secondary School in Highbury, a stone''s throw from The Arsenal soccer club, the area in which he grew up. A Former World Class Trampolinist turned stunt professional he has worked on some of Hollywoods biggest grossing movies and has stunt doubled some of the biggest stars in the world.Now as a Stunt Coordinator, Action Designer and Action Unit Director he brings realistic innovative action sequences to the big screen.::Anonymous', NULL, NULL, NULL, NULL, 'Theo Kypri');
INSERT INTO imdb.person VALUES ('2954059', 'Talbott Lin is an actor, known for When We First Met (2017), Atlanta (2016) and The Big Bang Theory (2007).::Anonymous', NULL, NULL, NULL, NULL, 'Talbott Lin');
