INSERT INTO imdb.person VALUES ('1977883', 'Nina Hartmann was born on November 27, 1981 in Rum, Tyrol, Austria. She is an actress and writer, known for Mission: Impossible - Rogue Nation (2015), Die Akte Golgatha (2010) and Lange Leitung!? (2017).::Anonymous', NULL, NULL, '1981-11-27', NULL, 'Nina Hartmann');
