INSERT INTO imdb.person VALUES ('5020928', 'Martyn Mayger was born 1955 in West London. After many years working in a wide variety of jobs, he ran his own Record Shop from 1989 until 2007. Also a very experienced drummer and percussionist in various styles of music but working as a Professional Film and TV Extra is now his main occupation.::Martyn Mayger', NULL, NULL, NULL, NULL, 'Martyn Mayger');
