INSERT INTO imdb.person VALUES ('5387921', 'Stephen McDade was born in Guildford, Surrey and grew up in the small village of Bramley. He attended Bramley Primary School before completing his education at Glebelands School in Cranleigh. He has always had a strong love of films and theatre, and after years of working in other industries decided to move to working in front of the camera. He is married and has three children.::Agent', NULL, NULL, NULL, NULL, 'Stephen McDade');
