INSERT INTO imdb.person VALUES ('0457723', 'Annie Kitral is an actress, known for Jack Reacher (2012), My Bloody Valentine (2009) and Welcome to Collinwood (2002).::Anonymous', NULL, NULL, NULL, NULL, 'Annie Kitral');
