INSERT INTO imdb.person VALUES ('6491190', 'Hayley H. Long is an actress, known for Traces of Indignity (2018), The Nice Guys (2016) and The Founder (2016).::Anonymous', NULL, NULL, NULL, NULL, 'Hayley H. Long');
INSERT INTO imdb.person VALUES ('1941271', 'Dawn Chubai was born in Edmonton, Alberta, Canada. She is an actress, known for Fantastic 4: Rise of the Silver Surfer (2007), Mission: Impossible - Ghost Protocol (2011) and The Twilight Saga: Eclipse (2010). She has been married to Brad Pinnell since October 23, 2004.::Anonymous', NULL, NULL, NULL, NULL, 'Dawn Chubai');
INSERT INTO imdb.person VALUES ('1229830', 'Nicola Anderson is known for her work on The Age of Adaline (2015), Mission: Impossible - Ghost Protocol (2011) and Supernatural (2005).::Anonymous', NULL, NULL, NULL, NULL, 'Nicola Anderson');
