INSERT INTO imdb.person VALUES ('8990401', 'Timothy Allsop grew up in Suffolk, UK and trained at the Guildhall School of Music and Drama. He has appeared in The Mummy (2017), Captain Phillips (2013) and Detectorsts (2014 BBC). He has worked in theatre for 10 years appearing at the Royal National Theatre and Shakespeare''s Globe. His novel, The Smog, is published by Amper and Sand (2017).::Timothy Allsop', NULL, NULL, NULL, NULL, 'Timothy Allsop');
