INSERT INTO imdb.person VALUES ('5563594', 'Sammy Oussama was born in Paris, France, now lives in Orange County CA. Sam first performed as a Scientist "Voyage dans le Temps" in a French play at age 15. He attended OCC and study Film. He become a SAG member in 2009. In Film, he''s appeared alongside (Reese Witherspoon in ''Rendition'' & Cameron Diaz as an under covered agent ''Knight & Day'' with Tom Cruise). He''s been working on many TV show''s including ( 24, NCIS, The Unit, Law in Order etc..), a number of Pilots such as (Larry''s Co-Worker "American Family'' and Arab guard ''Company Man''). And New Media ( Beacon Grille "Commercial"as a Director/Producer).::Sam', NULL, NULL, NULL, NULL, 'Sammy Oussama');
INSERT INTO imdb.person VALUES ('0989820', 'Stephen Radochia was born in Cambridge, Massachusetts, USA. He is an actor, known for American Hustle (2013), Knight and Day (2010) and Metal (2001).::Anonymous', NULL, NULL, NULL, NULL, 'Stephen Radochia');
