INSERT INTO imdb.person VALUES ('2913119', 'Lena Waithe was born on May 17, 1984 in Chicago, Illinois, USA as Lena Diane Waithe. She is a writer and actress, known for Bones (2005), Hello Cupid (2013) and Save Me (2011).::Anonymous', 'Lena Diane', 'Waithe', '1984-05-17', NULL, 'Lena Waithe');
