INSERT INTO imdb.person VALUES ('0181579', 'Rodrigo Cortés was born in 1973 in Pazos Hermos, Ourense, Galicia, Spain as Rodrigo Cortés Giráldez. He is a writer and editor, known for Buried - Sepolto (2010), Red Lights (2012) and Apartment 143 (2011).::Anonymous', 'Rodrigo Cortés', 'Giráldez', NULL, NULL, 'Rodrigo Cortés');
