INSERT INTO imdb.person VALUES ('2781962', 'Jessie Mueller was born on February 20, 1983 in Evanston, Illinois, USA. She is an actress, known for The 68th Annual Tony Awards (2014), The 66th Annual Tony Awards (2012) and The Horror Vault 2 (2009).::Anonymous', NULL, NULL, '1983-02-20', NULL, 'Jessie Mueller');
