INSERT INTO imdb.person VALUES ('1085519', 'Nina Gummich was born in 1991. She is an actress, known for Bridge of Spies (2015), Groupies bleiben nicht zum Frühstück (2010) and Allein unter Schülern (2009).::Anonymous', NULL, NULL, NULL, NULL, 'Nina Gummich');
