INSERT INTO imdb.person VALUES ('4266700', 'Casey Roberts was born in upstate NY, November 16 2001. He began his interest in acting after having performed on stage in several theater productions. Right after that, he started auditioning for film/tv roles and has been going strong ever since . In addition to acting, Casey enjoys his friends, activities, music and traveling.::Casey Roberts', NULL, NULL, NULL, NULL, 'Casey Roberts');
INSERT INTO imdb.person VALUES ('7047029', 'Zak Roland is known for his work on Katy in the Bush, Ep. 3 : Katy Starts a Skolliwol (2016), Katy in the Bush (2016) and Starting Out (2016).::Anonymous', NULL, NULL, NULL, NULL, 'Zak Roland');
INSERT INTO imdb.person VALUES ('5572316', 'Pavel Shatu is an actor and writer, known for 12 Kilometers (2016), Orange Is the New Black (2013) and Mountain Low (2014).::Anonymous', NULL, NULL, NULL, NULL, 'Pavel Shatu');
INSERT INTO imdb.person VALUES ('6685100', 'A late bloomer in the acting world, DJ Silver has started to make his mark on film and on TV, garnering respect in the industry in just a few short years. He has had numerous roles, and was recently rewarded for his efforts by landing one of the coveted featured blue swimmer roles in the upcoming comedy feature "The Nest."::DJ Silver', NULL, NULL, NULL, NULL, 'D.J. Silver');
INSERT INTO imdb.person VALUES ('7241881', 'Chris Sirois is an actor, known for Doctor Rick (2015), Bridge of Spies (2015) and Reversed Destiny (2016).::Anonymous', NULL, NULL, NULL, NULL, 'Chris Sirois');
