INSERT INTO imdb.person VALUES ('9065325', 'A natural born entertainer, Justin Mane is a trained Actor and Pro Wrestler located in Metro Detroit, Michigan. Best known for his appearance as "Jacob Kaye" on the April 27th, 2012 edition of WWE Smackdown. Has performed in multiple commercials locally and nationally, such as Rocket Mortgage, Michigan Power Rodding, Farm Bureau Insurance, SVS Vision, Brondes Ford Dealership in Toledo, etc.::Justin Mane', NULL, NULL, '1988-03-28', NULL, 'Justin Mane');
