INSERT INTO imdb.person VALUES ('1367863', 'Brandon Richardson was born on September 23, 1984 in Miami Beach, Florida, USA as Brandon Quantavius Richardson. He is an actor, and director, known for Horrible Bosses 2 (2014), Meet the Browns (2008), and Tundra II (2003). He graduated from University of Miami, also served in the US Army military during the Iraq War in 2007.::.', 'Brandon Quantavius', 'Richardson', '1984-09-23', NULL, 'Brandon Richardson');
