INSERT INTO imdb.person VALUES ('6591682', 'Shiming Zou was born on May 18, 1981 in Zunyi, Guizhou, China. He is an actor, known for Transformers: Age of Extinction (2014), Up Idol (2015) and Zou Shiming Courageous Warrior (2016). He has been married to Yingying Ran since February 5, 2011. They have two children.::Anonymous', NULL, NULL, '1981-05-18', NULL, 'Shiming Zou');
INSERT INTO imdb.person VALUES ('0934464', 'Calvin Wimmer is known for his work on Transformers (2007), Transformers: Revenge of the Fallen (2009) and Transformers: Dark of the Moon (2011).::Anonymous', NULL, NULL, NULL, NULL, 'Calvin Wimmer');
