INSERT INTO imdb.person VALUES ('0343722', 'Ted Grossman is known for his work on Star Wars: Episode VI - Return of the Jedi (1983), E.T. the Extra-Terrestrial (1982) and Indiana Jones and the Temple of Doom (1984).::Anonymous', NULL, NULL, NULL, NULL, 'Ted Grossman');
