INSERT INTO imdb.person VALUES ('0867704', 'He has appeared on Broadway numerous times, most recently this past season as Lemml in Paula Vogel''s Indecent, with Larry David in Fish in the Dark, with Al Pacino in Merchant of Venice, with Denzel Washington in Julius Caesar, with Mark Ruffalo in the Tony Award winning revival of Awake and Sing, with Ellen Barkin in the Tony Award winning revival of The Normal Heart, and with Morgan Freeman and Frances McDormand in The Country Girl, directed by Mike Nichols. He holds an MFA in Acting from NYU Graduate Acting Program and a BA in Political Science from Brown University. Originally from Larchmont, NY, he now lives in New York City with his wife, actress Eliza Foss, and their daughter.::Richard Topol', NULL, NULL, NULL, NULL, 'Richard Topol');
