INSERT INTO imdb.person VALUES ('0195844', 'Joseph D''Onofrio is known for many roles including young Tommy in Good Fellas, Slick in A Bronx Tale and his recurring role of Staten Island Mike on the Sitcom Are We There Yet? He has enjoyed both comedic and dramatic roles throughout his career.He is Born and raised in New York.::Maria Maio', NULL, NULL, NULL, NULL, 'Joseph D''Onofrio');
