INSERT INTO imdb.person VALUES ('2137710', 'Nancy Ozelli is an actress, known for The Producers (2005), 37 (2016) and The Audition (2016).::Anonymous', NULL, NULL, NULL, NULL, 'Nancy Ozelli');
