INSERT INTO imdb.person VALUES ('4430345', 'Jessica Petrik was born June 5th, 1988, in Farmington Hills, Michigan, USA. At the age of 18, after graduating high school, she went off to Ferris State University to pursue her degree in Television & Digital Media Production, where she also studied theater. In December 2008, she left Ferris to pursue a major in Digital Video Production at Washtenaw Community College. In August 2010, she received her Liberal Arts from Ferris State University & in December 2010 she received her Digital Video Production degree.::unknown', NULL, NULL, NULL, NULL, 'Jessica Petrik');
