INSERT INTO imdb.person VALUES ('1468093', 'Dan Forcey received his undergraduate degree in theatre with minors in physics and philosophy from the University of Southern California. He also holds his graduate degree in Acting with an emphasis on movement teaching from York University in Toronto, Canada, where he wrote his master''s thesis on the use of the British quarterstaff. He has worked extensively across the US and Canada for the last ten years, choreographing and teaching movement and stage combat. He has held faculty positions at York University, the Centre for Indiginous Theatre, the University of Southern California, Cal State University, Long Beach, and the Cerritos Center for the Performing Arts.::Daniel Forcey', NULL, NULL, '1974-02-13', NULL, 'Daniel Forcey');
INSERT INTO imdb.person VALUES ('2004404', 'Karen Gilchrist is known for her work on Iron Man 2 (2010), The Jungle Book (2016) and Iron Man (2008).::Anonymous', NULL, NULL, NULL, NULL, 'Karen Gilchrist');
