INSERT INTO imdb.person VALUES ('0511541', 'Damon Lindelof was born on April 24, 1973 in Teaneck, New Jersey, USA as Damon Laurence Lindelof. He is a writer and producer, known for Lost (2004), Tomorrowland (2015) and Prometheus (2012). He has been married to Heidi Fugeman since May 28, 2005. They have one child.::Anonymous', 'Damon Laurence', 'Lindelof', '1973-04-24', NULL, 'Damon Lindelof');
