INSERT INTO imdb.person VALUES ('4119640', 'Bill Martin was born as William Christopher Martin. He is an actor, known for Super 8 (2011), Banks of the Vltava (2011) and Leatherheads (2008). He has been married to Bobbi since July 8, 2006. They have three children.::Anonymous', 'William Christopher', 'Martin', NULL, NULL, 'Bill Martin');
INSERT INTO imdb.person VALUES ('2474864', 'Jake McLaughlin was born on October 7, 1982 in Paradise, California, USA as Jacob Adam McLaughlin. He is an actor, known for Warrior (2011), Quantico (2015) and In the Valley of Elah (2007). He has been married to Stephanie McLaughlin since 2004. They have four children.::Anonymous', 'Jacob Adam', 'McLaughlin', '1982-10-07', NULL, 'Jake McLaughlin');
