INSERT INTO imdb.person VALUES ('3864537', 'Giovanni Alabiso was born in Woburn, MA and still lives in the Boston area. He has performed stand-up comedy throughout New England and in New York City. He also performs improv and sketch comedy as well as on stage. He also owns a walking tour company in Historic Salem that specializes in witchcraft, history and Ghosts.::Giovanni Alabiso', NULL, NULL, NULL, NULL, 'Giovanni Alabiso');
