INSERT INTO imdb.person VALUES ('1795076', 'Tim Curcio grew up in West Palm Beach, Florida. He attended Southern Methodist University in Dallas, Texas.After college, Tim performed at the Upright Citizens Brigade Theater in New York for many years, on the Harold Teams, Beatrice & Beverly Hills, and the independent comedy troupe Rogue Elephant.Co-created the hit web series, Old Friends, Friend Us, and the short film, The Layla Project.Tim resides in Los Angeles with his wife, Meaghan, and their two children.::A stranger', 'Timothy Marc', 'Curcio', NULL, NULL, 'Tim Curcio');
