INSERT INTO imdb.person VALUES ('0015880', 'Khadija Alami is a producer and production manager, known for Captain Phillips (2013), Son of God (2014) and Our Kind of Traitor (2016).::Anonymous', NULL, NULL, NULL, NULL, 'Khadija Alami');
INSERT INTO imdb.person VALUES ('2224890', 'Michael Bronner is a journalist, screenwriter, producer and director. He has collaborated with director Paul Greengrass on the award-winning features United 93, Green Zone and Captain Phillips. A long-time staff producer at the weekday edition of 60 Minutes, his work has been recognized with a Peabody Award, the Edward R. Murrow Award for Investigative Reporting and several Emmy nominations. Bronner''s long-form magazine writing has been published in Vanity Fair and Foreign Policy, among others, and he is a founding editor of the not-for-profit online magazine Warscapes.::Michael Bronner', NULL, NULL, NULL, NULL, 'Michael Bronner');
