INSERT INTO imdb.person VALUES ('3917788', 'A.J. Rios was born as Anthony Joseph Rios. He is known for his work on Captain Phillips (2013), The Heat (2013) and Mildred''s Millions (2013).::Anonymous', 'Anthony Joseph', 'Rios', NULL, NULL, 'A.J. Rios');
