INSERT INTO imdb.person VALUES ('0005513', 'Hardly recognizable from one character to the next, Ubach has starred in over 100 theater, film and television projects, including the Peabody Award winning "Men of a Certain Age". She was noted by the New York Times as "a seriously talented actress" to "keep your eye on." She resides in Los Angeles with her husband and two dogs.::Simone Study', 'Alanna Noel', 'Ubach', '1975-10-03', NULL, 'Alanna Ubach');
