INSERT INTO imdb.person VALUES ('4702430', 'Actor and writer, Matt Nicholas was born in Syracuse, New York and raised in Pittsburgh, Pennsylvania. He has trained with the Pittsburgh Playhouse, at Tufts University, and with the Piven Theatre in Evanston, IL., and is fortunate to call Peter Linebaugh, Vincent Murphy and Jennifer Green as past instructors and inspirers.::Cal McKelvey', NULL, NULL, NULL, NULL, 'Matt Nicholas');
INSERT INTO imdb.person VALUES ('0644204', 'Lin Oeding was born on August 9, 1977 in Sacramento, California, USA. He is known for his work on The Equalizer (2014), Straight Outta Compton (2015) and Inception (2010).::Anonymous', NULL, NULL, '1977-08-09', NULL, 'Lin Oeding');
