INSERT INTO imdb.person VALUES ('4088427', 'Born in 1987, Windhoek, Namibia. Lived in Oman in the Middle East for 10 years.Started rowing in the UK at 11years oldJoined Leander Club and won the Thames Cup Challenge in Henley Royal Regatta amongst other notable regattas, represented England at Home Countries Regatta, represented GB in the U23 World Championships.Studying at Reading University, UK.::Leander biography', NULL, NULL, '1987-10-17', NULL, 'Ray Poulter');
