INSERT INTO imdb.person VALUES ('2222628', 'Wayne Marc Godfrey is the CEO, founder and owner of The Fyzz Facility, a prolific British production and finance company that has produced and part-funded over 200 feature films and invested over $280 million over the last 5 years. With an aggregate production spend in excess of US$2 billion, Wayne''s credits include ''The Foreigner'' starring Jackie Chan, ''47 Meters Down'', Martin Scorsese''s ''Silence'', ''Wind River'', ''The Yellow Birds'' and Rob Reiner''s ''Shock and Awe''.::Anonymous', NULL, NULL, '1981-11-30', NULL, 'Wayne Marc Godfrey');
