INSERT INTO imdb.person VALUES ('0525679', 'Andy was born & raised in Akron, Ohio. He attended Carnegie Mellon University in Pittsburgh, PA, graduating with a degree in Drama. Here he met his wife, Jayka Rivera. They have been married since 1997. His big brother Russell Lukich is also in show business as a special effects artist for such movies as "Jurassic Park III" and "A.I." He is a devoted fan of all Cleveland sports teams.::Anonymous', NULL, NULL, '1975-02-22', NULL, 'Andrew Lukich');
INSERT INTO imdb.person VALUES ('5000954', 'Carrington Bennett is an actor and director, known for Terms & Conditions (2016), Bad Coach (2015) and The Museum of Unnatural Gaming (2015).::Anonymous', NULL, NULL, NULL, NULL, 'Carrington Bennett');
