INSERT INTO imdb.person VALUES ('0732758', 'John Robinson is an actor, known for F2: Forensic Factor (2003), Zero Patience (1993) and Casino Jack (2010).::Anonymous', NULL, NULL, NULL, NULL, 'John Robinson');
