INSERT INTO imdb.person VALUES ('0714698', 'Lance Reddick was born in 1962 in Baltimore, Maryland, USA. He is an actor and producer, known for Fringe (2008), John Wick: Chapter 2 (2017) and John Wick (2014). He has been married to Stephanie Day since June 2011.::Anonymous', NULL, NULL, NULL, NULL, 'Lance Reddick');
