INSERT INTO imdb.person VALUES ('0404991', 'John W. Hyde is a producer and production manager, known for The Simpsons (1989), Das Boot (1981) and The Lost Boys (1987). He has been married to Kathleen Hyde since 2000.::Anonymous', NULL, NULL, NULL, NULL, 'John W. Hyde');
