INSERT INTO imdb.person VALUES ('4801913', 'Geoff was born and raised in Middlebury, Vermont. He graduated from Middlebury Union High School in 1987. He then studied Theatre and Archaeology at the University of Vermont, graduating in 1991. He earned his M.F.A. in Acting at the University of North Carolina-Greensboro in 2000. He moved to Brooklyn, NY in 2005.::Geoff Schuppert', NULL, NULL, NULL, NULL, 'Geoff Schuppert');
