INSERT INTO imdb.person VALUES ('2477239', 'Alex Beckett was born in Carmarthenshire, South Wales in 1982, and trained at Royal Academy of Dramatic Arts, London, graduating in 2003. He is an actor best known for his role as Barney Lumsden in BBC''s award-winning Twenty Twelve (2011), and W1A (2014-). Alex also has an extensive theatre CV.::Admin', NULL, NULL, NULL, NULL, 'Alex Beckett');
