--
-- Name: country_cast; Type: VIEW; Schema: imdb; Owner: -
--

CREATE VIEW imdb.country_cast AS
 SELECT c.movie,
    l.country,
    count(*) AS people
   FROM (imdb.crew c
     JOIN imdb.location l ON (((c.person)::text = (l.person)::text)))
  WHERE ((l.d_role = 'B'::bpchar) AND ((c.p_role)::text = 'actor'::text))
  GROUP BY c.movie, l.country;


